#define ACTIVE_MARK 4

static int stamp_ok(const char *s)
{
    size_t i;
    if (strlen(s) != 8) {
        return 0;
    }
    for (i = 0; i < 8; i++) {
        if (!isdigit((unsigned char)s[i]) && !(s[i] >= 'a' && s[i] <= 'f')) {
            return 0;
        }
    }
    return 1;
}

int xin_blob(const char *path, int *mark_out, char *stamp_out, size_t stamp_cap)
{
    FILE *fp;
    char line[256], stamp[32], name[64], cls[32], extra;
    int mark, id, rows = 0;

    if (path == NULL || stamp_out == NULL || stamp_cap < 9) {
        return 1;
    }
    fp = fopen(path, "r");
    if (fp == NULL) {
        return 1;
    }
    if (fgets(line, sizeof(line), fp) == NULL || strcmp(line, "REEL\n") != 0 ||
        fgets(line, sizeof(line), fp) == NULL ||
        sscanf(line, "MARK %d %c", &mark, &extra) != 1 || mark != ACTIVE_MARK ||
        fgets(line, sizeof(line), fp) == NULL || strcmp(line, "SLOT knit\n") != 0 ||
        fgets(line, sizeof(line), fp) == NULL ||
        sscanf(line, "STAMP %31s %c", stamp, &extra) != 1 || !stamp_ok(stamp)) {
        fclose(fp);
        return 1;
    }
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "CALL %63s %d %31s %c", name, &id, cls, &extra) != 3 ||
            strcmp(cls, "live") != 0) {
            fclose(fp);
            return 1;
        }
        rows++;
    }
    if (ferror(fp) || rows == 0) {
        fclose(fp);
        return 1;
    }
    fclose(fp);
    if (mark_out != NULL) {
        *mark_out = mark;
    }
    memcpy(stamp_out, stamp, 9);
    return 0;
}
