            strcmp(cls, "live") == 0 && strcmp(row_name, name) == 0) {
            fclose(fp);
            return 1;
        }
    }
    fclose(fp);
    return 0;
}

static int read_spool_call(const char *path, char *name)
{
    FILE *fp;
    char line[LINE_LEN], extra;

    fp = fopen(path, "r");
    if (fp == NULL) return -1;
    if (fgets(line, sizeof(line), fp) == NULL ||
        sscanf(line, "%63s %c", name, &extra) != 1 ||
        fgets(line, sizeof(line), fp) != NULL) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int cmd_spin(int argc, char **argv)
{
    const char *blob = CAPSET_PATH, *spool;
    char call[NAME_LEN], stamp[STAMP_LEN + 1], loaded[64];
    int mark = 0, admit_rc, covered;
    FILE *fp;

    if (argc == 1) {
        spool = argv[0];
    } else if (argc == 3 && strcmp(argv[0], "--blob") == 0) {
        blob = argv[1];
        spool = argv[2];
    } else {
        fprintf(stderr, "usage: nockreel spin [--blob PATH] SPOOL\n");
        return 2;
    }

    unlink(ACCEPT_PATH);
    unlink(LOADED_SET_PATH);
    if (read_spool_call(spool, call) != 0 || !desc_has(call)) {
        return 1;
    }
    admit_rc = xin_blob(blob, &mark, stamp, sizeof(stamp));
    if (admit_rc != 0 || sel_bank(admit_rc) != 0) {
        return 1;
    }
    covered = blob_has(blob, call);
    snprintf(loaded, sizeof(loaded), "table:%s", stamp);

    fp = fopen(LOADED_SET_PATH, "w");
    if (fp == NULL || fprintf(fp, "%s\n", loaded) < 0 || fclose(fp) != 0) {
        if (fp != NULL) fclose(fp);
        unlink(LOADED_SET_PATH);
        return 1;
    }
    fp = fopen(ACCEPT_PATH, "w");
    if (fp == NULL || fputs("1\n", fp) == EOF || fclose(fp) != 0) {
        if (fp != NULL) fclose(fp);
        unlink(ACCEPT_PATH);
        unlink(LOADED_SET_PATH);
        return 1;
    }
    printf("{\"loaded\":\"%s\",\"status\":\"%s\",\"call\":\"%s\"}\n",
           loaded, covered ? "replayed" : "unsupported", call);
    (void)mark;
    return 0;
}
